"""Explicit 4+4 text-bank metadata around the unchanged cached C4 detector."""

from copy import deepcopy

from audio_deepfake_detection.experiments.layer_fusion.model import LayerFusionDetector
from audio_deepfake_detection.lacf.model import TEMPLATES


COMMON = (
    "genuine human speech",
    "a real person speaking in their own voice",
    "an authentic human voice",
    "speech produced by a human speaker",
    "speech generated by a computer from written text",
    "a voice digitally converted to sound like another person",
    "a fake copy of a person's voice created by AI cloning",
)
FINAL_CONCEPT = {
    "vocoder": "speech synthesized by a neural vocoder",
    "neural_synthesis": "speech synthesized artificially by a neural network",
}
GROUPS = {"bona_fide": [0, 1, 2, 3], "spoof": [4, 5, 6, 7]}


def bank_definition(name):
    if name not in FINAL_CONCEPT:
        raise ValueError("Expected vocoder or neural_synthesis bank")
    return {"name": name, "concepts": [*COMMON, FINAL_CONCEPT[name]],
            "templates": list(TEMPLATES), "group_indices": deepcopy(GROUPS),
            "temperature": 0.07, "uniform_spoof_mass": 0.5,
            "prototype_policy": "normalize_each_template_then_mean_then_normalize"}


class ConceptBankMoE(LayerFusionDetector):
    """Only fixed text prototypes differ; original audio, routing and BCE math remain."""

    def __init__(self, name, prototypes):
        bank_definition(name)
        object.__setattr__(self, "bank_name", name)
        super().__init__("C4", prototypes)

    @property
    def objective(self):
        if self.backend.config.semantic_loss or self.backend.config.bonafide_loss:
            raise ValueError("This bank comparison requires detection BCE only")
        return self.backend.objective

    def configuration(self):
        result = super().configuration()
        definition = bank_definition(self.bank_name)
        result["backend"].update(definition)
        result["concept_bank"] = definition
        result["model_name"] = "LACF Layer-MoE with balanced text concepts"
        result["semantic_loss"] = False
        result["bonafide_loss"] = False
        return result
